CREATE OR ALTER PROCEDURE [dbo].[uspUserExternalIdentity_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @UserId UNIQUEIDENTIFIER = NULL
	, @EmployeeId UNIQUEIDENTIFIER = NULL
	, @IntegrationChannelId UNIQUEIDENTIFIER = NULL
	, @IdentityStatus NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[UserId]
			, t.[EmployeeId]
			, t.[IntegrationChannelId]
			, t.[ExternalUserId]
			, t.[ExternalUsername]
			, t.[DisplayName]
			, t.[LinkedAt]
			, t.[IdentityStatus]
			, t.[LastSeenAt]
			, t.[CreatedDate]
		FROM [dbo].[UserExternalIdentity] AS t
		
		WHERE (ISNULL(@SearchText, '') = '' OR t.[DisplayName] LIKE CONCAT('%', @SearchText, '%'))
			AND (@UserId IS NULL OR t.[UserId] = @UserId)
			AND (@EmployeeId IS NULL OR t.[EmployeeId] = @EmployeeId)
			AND (@IntegrationChannelId IS NULL OR t.[IntegrationChannelId] = @IntegrationChannelId)
			AND (ISNULL(@IdentityStatus, '') = '' OR t.[IdentityStatus] = @IdentityStatus)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'userId' THEN r.[UserId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'userId' THEN r.[UserId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'employeeId' THEN r.[EmployeeId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'employeeId' THEN r.[EmployeeId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'integrationChannelId' THEN r.[IntegrationChannelId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'integrationChannelId' THEN r.[IntegrationChannelId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'externalUserId' THEN r.[ExternalUserId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'externalUserId' THEN r.[ExternalUserId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'externalUsername' THEN r.[ExternalUsername] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'externalUsername' THEN r.[ExternalUsername] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'displayName' THEN r.[DisplayName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'displayName' THEN r.[DisplayName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'linkedAt' THEN r.[LinkedAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'linkedAt' THEN r.[LinkedAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'identityStatus' THEN r.[IdentityStatus] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'identityStatus' THEN r.[IdentityStatus] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'lastSeenAt' THEN r.[LastSeenAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'lastSeenAt' THEN r.[LastSeenAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
